ALTER TABLE public.extracted_design_elements ADD COLUMN document_id uuid REFERENCES public.design_documents(id), ADD COLUMN extracted_text text, ADD COLUMN extraction_method text NOT NULL DEFAULT 'unknown', ADD COLUMN source_location jsonb, ADD COLUMN corrected_text text, ADD COLUMN corrected_by uuid REFERENCES public.profiles(id), ADD COLUMN corrected_at timestamptz;
UPDATE public.extracted_design_elements e SET document_id=v.document_id,extracted_text=coalesce(e.source_quote,e.name) FROM public.design_versions v WHERE v.id=e.design_version_id;
ALTER TABLE public.extracted_design_elements ADD CONSTRAINT extraction_method_known CHECK(extraction_method IN ('embedded_text','ocr','processor','unknown')), ADD CONSTRAINT correction_actor_pair CHECK((corrected_text IS NULL AND corrected_by IS NULL AND corrected_at IS NULL) OR (corrected_text IS NOT NULL AND corrected_by IS NOT NULL AND corrected_at IS NOT NULL));
CREATE TABLE public.document_processing_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id),document_id uuid NOT NULL REFERENCES public.design_documents(id),design_version_id uuid NOT NULL REFERENCES public.design_versions(id),requested_by uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed')),provider_job_id text,error text,page_metadata jsonb NOT NULL DEFAULT '[]'::jsonb,provider_result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.document_processing_jobs TO authenticated;GRANT ALL ON public.document_processing_jobs TO service_role;
ALTER TABLE public.document_processing_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY processing_job_read ON public.document_processing_jobs FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE UNIQUE INDEX one_active_document_job ON public.document_processing_jobs(design_version_id) WHERE status IN ('queued','running');
CREATE FUNCTION public.validate_processing_references() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.design_versions v WHERE v.id=NEW.design_version_id AND v.document_id=NEW.document_id AND v.project_id=NEW.project_id) THEN RAISE EXCEPTION 'Document, version and project must match';END IF;RETURN NEW;END $$;
CREATE TRIGGER processing_reference_check BEFORE INSERT OR UPDATE ON public.document_processing_jobs FOR EACH ROW EXECUTE FUNCTION public.validate_processing_references();
CREATE TRIGGER extracted_reference_check BEFORE INSERT OR UPDATE ON public.extracted_design_elements FOR EACH ROW EXECUTE FUNCTION public.validate_processing_references();
CREATE FUNCTION public.correct_extracted_item(_id uuid,_text text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item public.extracted_design_elements;BEGIN SELECT * INTO item FROM public.extracted_design_elements WHERE id=_id FOR UPDATE;
IF auth.uid() IS NULL OR item.id IS NULL OR NOT public.project_access(item.project_id,ARRAY['administrator','project_manager','engineer','reviewer']::public.organization_role[]) THEN RAISE EXCEPTION 'Engineering membership required' USING ERRCODE='42501';END IF;
IF _text IS NULL OR length(trim(_text))=0 OR length(_text)>20000 THEN RAISE EXCEPTION 'Correction must contain 1 to 20000 characters';END IF;
UPDATE public.extracted_design_elements SET corrected_text=_text,corrected_by=auth.uid(),corrected_at=now() WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.correct_extracted_item(uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.correct_extracted_item(uuid,text) TO authenticated,service_role;
COMMENT ON COLUMN public.extracted_design_elements.corrected_text IS 'Human transcription correction only. Raw extraction and verification status remain unchanged.';